export const analyzeMessage = async (message: string, historySignatures: ScamSignature[] = []): Promise<ScamAnalysis> => {
  const response = await fetch('/rakshak', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      conversation_id: "UI",
      message: message,
      history: []
    })
  });

  if (!response.ok) {
    throw new Error(`Rakshak API Error: ${response.statusText}`);
  }

  const data: AgentResponse = await response.json();

  // Transform AgentResponse to ScamAnalysis for the UI
  const analysis: ScamAnalysis = {
    isScam: data.is_scam,
    confidence: data.confidence_score,
    scamType: data.scam_type,
    channel: 'text',
    threatLevel: data.is_scam ? (data.confidence_score > 0.8 ? 'High' : 'Medium') : 'Low',
    summary: data.agent_reply || "Analysis complete.",
    safetyAlert: data.is_scam ? `Detection: Suspicious ${data.scam_type} pattern identified.` : "No immediate threat identified.",
    extractedInfo: {
      upiIds: (data.extracted_intelligence?.upi_ids || []).map(v => ({ value: v, confidence: 95, timestamp: Date.now() })),
      bankDetails: (data.extracted_intelligence?.bank_accounts || []).map(v => ({ value: typeof v === 'string' ? v : JSON.stringify(v), confidence: 95, timestamp: Date.now() })),
      ifscCodes: (data.extracted_intelligence?.ifsc_codes || []).map(v => ({ value: v, confidence: 95, timestamp: Date.now() })),
      phoneNumbers: (data.extracted_intelligence?.phone_numbers || []).map(v => ({ value: v, confidence: 95, timestamp: Date.now() })),
      links: (data.extracted_intelligence?.phishing_urls || []).map(v => ({ value: v, confidence: 95, timestamp: Date.now() })),
      cryptoWallets: [],
      fakeIdentities: []
    },
    killChainStage: data.is_scam ? 'Exploitation' : 'Delivery',
    fingerprint: {
      primaryHandle: data.extracted_intelligence?.upi_ids?.[0] || '',
      primaryPhone: data.extracted_intelligence?.phone_numbers?.[0] || '',
      primaryLink: data.extracted_intelligence?.phishing_urls?.[0] || '',
      category: data.scam_type
    },
    recommendedActions: data.is_scam 
      ? ["Do not transfer money.", "Block this sender.", "Enable two-factor authentication."] 
      : ["Stay vigilant.", "Check official channels."],
    timestamp: Date.now(),
    originalMessage: message,
    messages: data.is_scam ? [{ role: 'scammer', content: message, timestamp: Date.now() }] : []
  };

  if (analysis.isScam) {
    analysis.guardianGuidance = await generateGuardianGuidance(analysis);
  }

  return analysis;
};

export const generateGuardianGuidance = async (analysis: any): Promise<GuardianGuidance> => {
  return withRetry(async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Provide guidance for this detected scam: ${JSON.stringify(analysis)}`,
      config: {
        responseMimeType: "application/json",
        systemInstruction: GUARDIAN_PERSONA_DIRECTIVE,
      }
    });
    return safeJsonParse(response.text);
  });
};

export const generateAgenticBait = async (conversationId: string, history: { role: string, content: string }[]): Promise<AgentResponse> => {
  return withRetry(async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const latestMessage = history[history.length - 1]?.content || "";
    const conversationHistory = history.slice(0, -1);

    const contents = conversationHistory.map(h => ({
      role: h.role === 'scammer' ? 'user' : 'model',
      parts: [{ text: h.content }]
    }));

    contents.push({
