interface Props {
  logs: IntelligenceLog[];
  onRunSimulation?: (count: number) => void;
  hasKey?: boolean;
  onOpenKey?: () => void;
}

const WarRoom: React.FC<Props> = ({ logs, onRunSimulation, hasKey, onOpenKey }) => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedId, setGeneratedId] = useState<string | null>(null);
  const [forgeLog, setForgeLog] = useState<string[]>(["SYSTEM_READY", "AWAITING_INPUT"]);

  const runForge = async (type: string) => {
    setIsGenerating(true);
    setForgeLog(prev => [`INITIATING_${type}_SYNTHESIS`, ...prev]);
    try {
      const prompt = type === 'ID' 
        ? "high-security government identification card with blurred personal data"
        : "official-looking bank statement from a major Indian bank";

      const url = await generateSyntheticBaitImage(prompt);
      setGeneratedId(url);
      setForgeLog(prev => [`${type}_SUCCESSFULLY_FORGED`, ...prev]);
    } catch (e) {
      setForgeLog(prev => [`SYNTHESIS_ERROR: ${e}`, ...prev]);
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in fade-in duration-700">
