             <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Persona: Vulnerable Citizen</p>
           </div>
        </div>
        <div className="text-[10px] font-mono text-slate-400 bg-black/40 px-3 py-1 rounded">
          SESSION_ID: {sessionId.substring(0, 8)}...
        </div>
      </header>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-4 no-scrollbar bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]">
        {safeMessages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'scammer' ? 'justify-start' : 'justify-end'}`}>
            <div className={`max-w-[85%] space-y-1 ${m.role === 'scammer' ? 'items-start' : 'items-end'} flex flex-col`}>
               <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest px-2">
                 {m.role === 'scammer' ? 'Target' : 'AI-Agent'}
               </span>
               <div className={`px-5 py-3 rounded-2xl text-sm leading-relaxed shadow-lg ${
