        {isTyping && (
          <div className="flex justify-end">
             <div className="bg-blue-600/20 px-4 py-3 rounded-2xl rounded-br-none border border-blue-500/20 flex space-x-1">
                <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce" />
                <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce [animation-delay:0.2s]" />
                <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce [animation-delay:0.4s]" />
             </div>
          </div>
        )}
      </div>

      <div className="p-4 bg-black/50 border-t border-white/5">
        <form 
          onSubmit={(e) => {
            e.preventDefault();
            handleManualScammerReply(input);
          }}
          className="relative"
        >
          <input 
            value={input}
