};

const safeJsonParse = (text: string) => {
  try {
    return JSON.parse(text);
  } catch (e) {
    const cleaned = text.replace(/```json\n?|```/g, '').trim();
    try {
      return JSON.parse(cleaned);
    } catch (e2) {
      console.error("Failed to parse JSON from response:", text);
      throw new Error("Invalid intelligence format received.");
    }
  }
};

async function withRetry<T>(fn: () => Promise<T>, retries = 3, delay = 2000): Promise<T> {
  try {
    const result = await fn();
    apiStatus.isThrottled = false;
    return result;
  } catch (error: any) {
    const isRateLimit = error?.message?.includes('429') || error?.status === 429;

    if (isRateLimit) {
      apiStatus.isThrottled = true;
      apiStatus.lastThrottleTime = Date.now();
      console.warn(`[BCR-API] Rate limit hit. Cooling down for ${delay}ms...`);
    }

    if (retries > 0 && (isRateLimit || error?.message?.includes('500') || error?.message?.includes('503'))) {
      // Exponential backoff: increase delay for next attempt
      await new Promise(resolve => setTimeout(resolve, delay));
      return withRetry(fn, retries - 1, delay * 2);
    }

    if (isRateLimit) {
      throw new Error("API Quota Exceeded. Please pause for 60 seconds. High 'Thinking Budget' usage detected.");
    }
    throw error;
  }
}

