import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality, Blob } from '@google/genai';
import { decodeBase64, decodeAudioData } from '../services/geminiService';
import { ScamAnalysis } from '../types';

interface Props {
  onAlert: (analysis: ScamAnalysis) => void;
}

const LiveShield: React.FC<Props> = ({ onAlert }) => {
  const [isActive, setIsActive] = useState(false);
  const [transcription, setTranscription] = useState<string[]>([]);
  const [lastSafetyAlert, setLastSafetyAlert] = useState<string | null>(null);
  const [threatLevel, setThreatLevel] = useState<'Low' | 'Medium' | 'High'>('Low');

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const frameIntervalRef = useRef<number | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const waveformRef = useRef<HTMLDivElement>(null);

  function encode(bytes: Uint8Array) {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  }

  function createBlob(data: Float32Array): Blob {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
      int16[i] = data[i] * 32768;
    }
    return {
      data: encode(new Uint8Array(int16.buffer)),
      mimeType: 'audio/pcm;rate=16000',
    };
  }

  const startShield = async () => {
    setIsActive(true);
    setTranscription([]);
    setLastSafetyAlert(null);
    setThreatLevel('Low');
    nextStartTimeRef.current = 0;

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      if (videoRef.current) videoRef.current.srcObject = stream;

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = outputAudioContext;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContext.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContext.destination);

            const ctx = canvasRef.current?.getContext('2d');
            // Increased interval to 5000ms to conserve API tokens/requests
            frameIntervalRef.current = window.setInterval(() => {
              if (videoRef.current && canvasRef.current && ctx) {
                canvasRef.current.width = 160; // Lower resolution
                canvasRef.current.height = 120;
                ctx.drawImage(videoRef.current, 0, 0, 160, 120);
                const base64 = canvasRef.current.toDataURL('image/jpeg', 0.3).split(',')[1];
                sessionPromise.then(s => s.sendRealtimeInput({ media: { data: base64, mimeType: 'image/jpeg' } }));
              }
            }, 5000); 
          },
          onmessage: async (msg: LiveServerMessage) => {
            if (msg.serverContent?.inputTranscription) {
              const text = msg.serverContent.inputTranscription.text;
              setTranscription(prev => [...prev.slice(-4), `Detecting: ${text}`]);
              checkScamTriggers(text);
            }
            if (msg.serverContent?.outputTranscription) {
              const text = msg.serverContent.outputTranscription.text;
              setTranscription(prev => [...prev.slice(-4), `AI Shield: ${text}`]);
            }

            const base64EncodedAudioString = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (base64EncodedAudioString && audioContextRef.current) {
              const ctx = audioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const audioBuffer = await decodeAudioData(decodeBase64(base64EncodedAudioString), ctx);
              const source = ctx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
              });

              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
            }

            if (msg.serverContent?.interrupted) {
              for (const source of sourcesRef.current.values()) {
                try { source.stop(); } catch(e) {}
                sourcesRef.current.delete(source);
              }
              nextStartTimeRef.current = 0;
            }
          },
          onerror: (e) => console.error("LiveShield Error", e),
          onclose: (e) => console.debug("LiveShield Closed", e),
        },
        config: {
          responseModalalities: [Modality.AUDIO],
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          systemInstruction: `You are Bharat Cyber Rakshak, a voice-first cyber safety assistant.
          Your role is to protect the citizen from scams in real-time.

          VOICE-FIRST SAFETY PROTOCOL:
          1. Monitor the audio and video feed for pressure tactics, authority impersonation (Police/Customs), or banking tricks.
          2. If a scam is detected, IMMEDIATELY speak to the user clearly and calmly.
          3. Say clearly: "This is a scam. Please do not send any money and do not share your OTP."
          4. Guide the user in simple words: "Please end this call now. You are safe. I am here to support you."
          5. Never use technical jargon. Use slow, clear, and reassuring sentences.

          Provide guidance ONLY if a scam is highly likely to avoid disturbing legitimate conversations.`
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error("Shield activation failed", err);
      setIsActive(false);
    }
  };

  const checkScamTriggers = (text: string) => {
    const triggers = ['otp', 'bank login', 'police', 'customs', 'arrest', 'urgent', 'payment', 'upi', 'account frozen', 'grandson', 'relative', 'win', 'lottery', 'kyc'];
    const lowerText = text.toLowerCase();
    const found = triggers.filter(t => lowerText.includes(t));

    if (found.length > 0) {
      setThreatLevel('High');
      const safetyMsg = `⚠️ ALERT: THIS IS A SCAM. Please do not send any money or share any details. You are safe. End the call now.`;
      setLastSafetyAlert(safetyMsg);

      onAlert({
        isScam: true,
        confidence: 0.95,
        scamType: "Real-time Voice Fraud",
        channel: 'call',
        threatLevel: 'High',
        summary: `Scam detected. Scammer mentioned: ${found.join(', ')}.`,
        safetyAlert: safetyMsg,
        extractedInfo: { upiIds: [], bankDetails: [], ifscCodes: [], phoneNumbers: [], links: [], cryptoWallets: [], fakeIdentities: [] },
        killChainStage: 'Exploitation',
        fingerprint: { primaryHandle: 'VOICE_FEED', primaryPhone: '', primaryLink: '', category: 'Voice' },
        recommendedActions: ["Hang up now.", "Do not press any buttons.", "Keep your banking apps closed."]
      });
    }
  };

  const stopShield = () => {
    if (sessionRef.current) sessionRef.current.close();
    if (frameIntervalRef.current) clearInterval(frameIntervalRef.current);
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
    }
    setIsActive(false);
  };

  useEffect(() => {
    return () => stopShield();
  }, []);

  return (
    <div className="bg-[#0f172a] rounded-[3rem] shadow-2xl border border-white/5 overflow-hidden relative">
      <div className={`px-10 py-8 flex items-center justify-between border-b border-white/5 ${isActive ? 'bg-blue-600/10' : 'bg-slate-900/50'}`}>
        <div className="flex items-center space-x-6">
          <div className={`p-4 rounded-3xl ${isActive ? 'bg-blue-500 shadow-[0_0_25px_#3b82f6]' : 'bg-white/5'}`}>
            <svg className={`w-8 h-8 ${isActive ? 'text-white' : 'text-slate-600'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
          </div>
          <div>
            <h3 className="text-2xl font-black text-white uppercase tracking-tight">Voice Safety Shield</h3>
            <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.4em] mt-1">{isActive ? 'PROTECTING CITIZEN WITH CALM VOICE GUIDANCE' : 'VOICE-FIRST ASSISTANT STANDBY'}</p>
          </div>
        </div>
        <div className="flex items-center space-x-4">
           {isActive && (
             <div className="flex items-center space-x-3 bg-blue-500/10 border border-blue-500/20 px-6 py-2 rounded-2xl">
                <div className="w-2 h-2 bg-blue-500 rounded-full animate-ping"></div>
                <span className="text-[10px] font-black text-blue-500 uppercase tracking-widest">Live Voice Monitoring</span>
             </div>
           )}
           <button
             onClick={isActive ? stopShield : startShield}
             className={`px-8 py-3 rounded-2xl font-black text-xs uppercase tracking-[0.2em] transition-all active:scale-[0.98] shadow-2xl ${
               isActive 
               ? 'bg-red-600 text-white hover:bg-red-500 shadow-red-900/40' 
               : 'bg-blue-600 text-white hover:bg-blue-500 shadow-blue-900/40'
             }`}
           >
             {isActive ? 'Stop Shield' : 'Start Shield'}
           </button>
        </div>
      </div>

      <div className="p-10 grid grid-cols-1 lg:grid-cols-2 gap-10">
        <div className="space-y-8">
          <div className="aspect-video bg-black rounded-[2.5rem] overflow-hidden relative shadow-inner border border-white/5 group">
             <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover grayscale opacity-20 transition-opacity group-hover:opacity-40" />
             <canvas ref={canvasRef} className="hidden" />

             {isActive && (
               <div className="absolute inset-0 pointer-events-none flex flex-col justify-between p-8">
                 <div className="flex justify-between items-start">
                    <div className="text-[10px] font-black text-blue-500 uppercase tracking-[0.4em] bg-blue-600/10 px-3 py-1.5 rounded-full border border-blue-500/20 backdrop-blur-md">Live Voice Security</div>
                    <div className="text-[10px] font-mono text-slate-500 bg-black/40 px-3 py-1 rounded">CALM_MODE_ENABLED</div>
                 </div>

                 <div className="h-24 flex items-end space-x-1 px-4">
                    {[...Array(40)].map((_, i) => (
                      <div 
                        key={i} 
                        className="flex-1 bg-blue-600/40 rounded-t-full transition-all duration-75" 
                        style={{ height: isActive ? `${20 + Math.random() * 80}%` : '5%' }} 
                      />
                    ))}
                 </div>

                 <div className="space-y-3">
                    {transcription.map((line, i) => (
                      <div key={i} className={`text-xs font-bold px-5 py-2.5 rounded-2xl w-fit animate-in slide-in-from-left-2 backdrop-blur-2xl border ${
                        line.startsWith('AI') 
                        ? 'bg-blue-600 text-white border-blue-400/30' 
                        : 'bg-white/10 text-white border-white/5'
                      }`}>
                        {line}
                      </div>
                    ))}
                 </div>
               </div>
             )}

             {!isActive && (
               <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-800 space-y-4">
                 <svg className="w-16 h-16 opacity-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
                 <p className="text-[10px] font-black uppercase tracking-[0.5em] italic">Voice Shield Standby</p>
               </div>
             )}
          </div>
          <div className="bg-blue-900/20 p-4 rounded-2xl border border-blue-500/20 text-[10px] text-blue-300 italic text-center">
            * Frame frequency adjusted to optimize system resources and conserve API tokens.
          </div>
        </div>

        <div className="flex flex-col space-y-10">
          <div className={`flex-1 p-10 rounded-[3rem] border transition-all duration-700 flex flex-col items-center justify-center text-center space-y-8 shadow-2xl relative overflow-hidden ${
            threatLevel === 'High' ? 'bg-red-600/10 border-red-500/30' : 'bg-black/40 border-white/5'
          }`}>
            {threatLevel === 'High' ? (
              <>
                <div className="w-24 h-24 bg-red-600 rounded-[2rem] flex items-center justify-center shadow-xl shadow-red-500/40 animate-bounce relative z-10">
                  <svg className="w-12 h-12 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                </div>
                <div className="relative z-10 space-y-4">
                  <h4 className="text-4xl font-black text-red-500 uppercase tracking-tighter">Scam Trick Detected</h4>
                  <p className="text-xl font-bold text-white leading-tight px-4">{lastSafetyAlert}</p>
                </div>
                <div className="pt-4 flex flex-col space-y-4 w-full max-w-sm relative z-10">
                  <button className="w-full py-4 bg-red-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-red-500 shadow-xl transition-all active:scale-95">Follow Instructions & Stay Safe</button>
                  <button onClick={() => setThreatLevel('Low')} className="w-full py-4 bg-white/5 text-slate-500 hover:text-white rounded-2xl text-[10px] font-black uppercase tracking-widest border border-white/5 transition-all">End Call Now</button>
                </div>
              </>
            ) : (
              <>
                <div className={`w-24 h-24 rounded-[2rem] flex items-center justify-center transition-all relative ${isActive ? 'bg-blue-600 shadow-[0_0_40px_rgba(59,130,246,0.3)]' : 'bg-white/5'}`}>
                  {isActive && <div className="absolute inset-0 bg-blue-500 rounded-[2rem] animate-ping opacity-20" />}
                  <svg className={`w-12 h-12 ${isActive ? 'text-white' : 'text-slate-700'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                </div>
                <div className="space-y-4">
                  <h4 className="text-2xl font-black text-white uppercase tracking-tight">{isActive ? 'I am listening...' : 'Ready to help'}</h4>
                  <p className="text-sm font-medium text-slate-500 max-w-sm mx-auto leading-relaxed">
                    {isActive 
                      ? "I am monitoring for tricks and scams. I will speak to you in a calm voice if I find anything suspicious." 
                      : "The Voice Shield is designed for everyone. I use simple words and a calm voice to keep you safe."}
                  </p>
                </div>
              </>
            )}
          </div>

          <div className="bg-white/5 border border-white/5 rounded-[2.5rem] p-8 flex flex-col justify-between h-48">
             <div className="flex justify-between items-center text-[10px] font-black text-blue-500 uppercase tracking-[0.4em]">
                <span>Voice Clarity Check</span>
                <span>Active Safety Listen</span>
             </div>
             <div className="flex items-end space-x-1 flex-1 py-4">
