          {/* Guardian Guidance */}
          {guardian && (
            <div className="space-y-8">
              <div className="bg-slate-50 rounded-[2.5rem] p-10 space-y-6 border border-slate-100">
                <h3 className="text-2xl font-black text-navy-900 leading-tight">
                  {guardian.user_alert || "Caution required."}
                </h3>

                <div className="space-y-4">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Recommended Safety Steps</h4>
                  <div className="grid grid-cols-1 gap-3">
                    {(guardian.what_to_do_now || []).map((step, i) => (
                      <div key={i} className="flex items-center space-x-4 bg-white p-5 rounded-2xl border border-slate-100 shadow-sm transition-all hover:border-blue-300">
                        <div className="w-8 h-8 rounded-xl bg-blue-600 text-white flex items-center justify-center font-black text-sm">{i + 1}</div>
                        <span className="text-sm font-bold text-slate-700 leading-relaxed">{step}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          )}

          <div className="flex justify-center pt-6">
            <button onClick={onClose} className="px-12 py-4 bg-slate-100 hover:bg-slate-200 text-slate-500 hover:text-navy-900 rounded-2xl font-black uppercase text-xs tracking-widest transition-all">
              Done
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

