        bankDetails: (data.extracted_intelligence?.bank_accounts || []).map((v: any) => ({ value: typeof v === 'string' ? v : JSON.stringify(v), confidence: 95, timestamp: Date.now() })),
        ifscCodes: (data.extracted_intelligence?.ifsc_codes || []).map((v: string) => ({ value: v, confidence: 95, timestamp: Date.now() })),
