           <NavBtn active={view === 'multimedia'} onClick={() => setView('multimedia')} label="Multimedia Defense" />
           <NavBtn active={view === 'intelligence'} onClick={() => setView('intelligence')} label="Tactical Grid" />
           <NavBtn active={view === 'warroom'} onClick={() => setView('warroom')} label="War Room" />
