                      </div>

                      <div className="flex flex-col items-center space-y-3">
                        <div className="text-[10px] font-black uppercase tracking-[0.5em] text-blue-400/60 mb-1">Judge Presentation Mode</div>
                        <button 
                          id="demo-trigger"
                          onClick={runDemo} 
                          className="group relative px-12 py-5 bg-slate-950 border-2 border-blue-500/50 rounded-full hover:border-blue-500 transition-all hover:bg-black hover:scale-105 active:scale-95 shadow-[0_0_50px_rgba(37,99,235,0.2)]"
                        >
                          <div className="absolute inset-0 bg-blue-600/10 rounded-full animate-pulse group-hover:bg-blue-600/20"></div>
                          <div className="relative flex items-center space-x-4">
