                            <span className="text-sm font-black uppercase tracking-[0.4em] text-blue-400 group-hover:text-white">Run Live Competition Demo</span>
                          </div>
                        </button>
                        <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest mt-2">Simulates a high-stakes KYC fraud scenario</p>
                   </div>
                </div>
             </div>

             <div id="results-anchor" />

             {latestAnalysis && (
               <div className="container mx-auto px-8 max-w-6xl py-20 space-y-20 animate-in slide-in-from-bottom-10">
                 <ResultPanel analysis={latestAnalysis.analysis} onClose={() => setLatestAnalysis(null)} />
                 {latestAnalysis.analysis.isScam && (
                    <div className="h-[850px]">
                      <BaitSession 
                        sessionId={latestAnalysis.sessionId}
                        initialMessages={latestAnalysis.analysis.messages}
                        onMessagesUpdate={(msgs) => setLogs(prev => prev.map(l => l.id === latestAnalysis.sessionId ? { ...l, messages: msgs } : l))}
                        onIntelExtracted={(info) => setLogs(prev => prev.map(l => l.id === latestAnalysis.sessionId ? { ...l, extractedInfo: info } : l))}
                        onOperationalReportGenerated={(report) => updateOperationalReport(latestAnalysis.sessionId, report)}
                      />
                    </div>
                 )}
               </div>
             )}
          </div>
        ) : view === 'intelligence' ? (
          <div id="threat-grid" className="container mx-auto px-8 py-16 max-w-7xl"><IntelligenceDashboard logs={logs} /></div>
        ) : view === 'warroom' ? (
          <div id="forge-panel" className="container mx-auto px-8 py-16 max-w-7xl"><WarRoom logs={logs} onRunSimulation={runSimulation} /></div>
        ) : view === 'history' ? (
          <div className="container mx-auto px-8 py-16 max-w-7xl"><CaseHistory logs={logs} onUpdateStatus={() => {}} onSendRequest={() => {}} /></div>
        ) : view === 'api' ? (
          <div className="container mx-auto px-8 py-16 max-w-7xl"><ApiDeveloperHub /></div>
        ) : (
          <div id="live-shield" className="container mx-auto px-8 py-16 max-w-7xl space-y-20 animate-in fade-in">
             <LiveShield onAlert={(analysis) => handleAnalysisComplete("LIVE_VOICE_INTERCEPT", analysis, true)} />
             <div className="h-[2px] bg-slate-200 w-full" />
             <VideoScanner />
          </div>
        )}
      </main>

      <div className="fixed top-1/2 right-6 -translate-y-1/2 flex flex-col space-y-4 z-[200]">
         <button onClick={runDemo} className="w-14 h-14 bg-blue-600 text-white rounded-2xl shadow-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all group relative">
            <span className="text-xl">🚀</span>
            <div className="absolute right-16 bg-slate-900 text-white text-[9px] font-black uppercase tracking-widest px-4 py-2 rounded-lg whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity border border-white/10 pointer-events-none">Start Demo</div>
         </button>
         <button onClick={() => setShowTour(true)} className="w-14 h-14 bg-slate-950 text-white rounded-2xl shadow-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all group relative">
            <span className="text-xl">🗺️</span>
            <div className="absolute right-16 bg-slate-900 text-white text-[9px] font-black uppercase tracking-widest px-4 py-2 rounded-lg whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity border border-white/10 pointer-events-none">Restart Tour</div>
         </button>
      </div>

      <button onClick={() => setShowTutor(true)} className="fixed bottom-10 left-10 z-[100] w-16 h-16 bg-slate-950 text-white rounded-3xl flex items-center justify-center shadow-2xl hover:scale-110 transition-all active:scale-95 group">
