export async function findLocalCyberCell(lat: number, lng: number): Promise<GroundingSource[]> {
  return withRetry(async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: "Where is the nearest official Cyber Crime Police Station or Cyber Cell? Please provide verified links and addresses.",
      config: {
        tools: [{ googleMaps: {} }],
        toolConfig: {
          retrievalConfig: {
            latLng: { latitude: lat, longitude: lng }
          }
        }
      }
    });

    const sources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.maps) {
          sources.push({
            title: chunk.maps.title || "Local Cyber Cell",
            uri: chunk.maps.uri,
            type: 'maps',
            address: chunk.maps.placeAnswerSources?.[0]?.reviewSnippets?.[0] || "Verified Authority"
          });
        }
      });
    }
    return sources;
  });
}

