export async function analyzeMessage(message: string, historySignatures: ScamSignature[] = []): Promise<ScamAnalysis> {
  const intensity = apiStatus.currentIntensity;

  return withRetry(async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: message,
      config: {
        responseMimeType: "application/json",
        systemInstruction: ANALYSIS_DIRECTIVE,
        tools: [{ googleSearch: {} }],
        thinkingConfig: { thinkingBudget: intensity === 'deep' ? 4000 : 2000 }
      }
    });

    const data = safeJsonParse(response.text || "{}");

    const groundingSources: GroundingSource[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web) {
          groundingSources.push({
            title: chunk.web.title || "Verified Report",
            uri: chunk.web.uri,
            type: 'web'
          });
        }
      });
    }

    const analysis: ScamAnalysis = {
      isScam: !!data.is_scam,
      confidence: data.confidence_level === 'high' ? 0.95 : data.confidence_level === 'medium' ? 0.75 : 0.45,
      scamType: data.scam_type || "Unclassified",
      channel: 'text',
      threatLevel: data.is_scam ? (data.confidence_level === 'high' ? 'High' : 'Medium') : 'Low',
      summary: data.reasoning || "Analysis complete.",
      safetyAlert: data.is_scam ? `Detection: Suspicious ${data.scam_type} pattern identified.` : "No immediate threat identified.",
      aiReasoningTrace: data.reasoning || "Autonomous extraction complete.",
      groundingSources: groundingSources,
      extractedInfo: {
        upiIds: (data.extracted_entities || []).filter((v: string) => v.includes('@')).map((v: string) => ({ value: v, confidence: 95, timestamp: Date.now() })),
        bankDetails: [],
        ifscCodes: [],
        phoneNumbers: (data.extracted_entities || []).filter((v: string) => /^\+?[0-9\s-]{10,15}$/.test(v)).map((v: string) => ({ value: v, confidence: 95, timestamp: Date.now() })),
        links: (data.extracted_links || []).map((v: string) => ({ value: v, confidence: 95, timestamp: Date.now() })),
        cryptoWallets: [],
        fakeIdentities: (data.extracted_entities || []).filter((v: string) => !v.includes('@') && !/^\+?[0-9\s-]{10,15}$/.test(v)).map((v: string) => ({ value: v, confidence: 95, timestamp: Date.now() }))
      },
      killChainStage: data.is_scam ? 'Exploitation' : 'Delivery',
      fingerprint: {
        primaryHandle: data.extracted_entities?.[0] || '',
        primaryPhone: '',
        primaryLink: data.extracted_links?.[0] || '',
        category: data.scam_type || "General Fraud"
      },
      recommendedActions: [data.recommended_action || (data.is_scam ? "Stay alert and do not share PII." : "No action needed.")]
    };

    if (analysis.isScam) {
      analysis.guardianGuidance = await generateGuardianGuidance(analysis);
    }

    return analysis;
  });
}

