// Fix: analyzeMessage uses gemini-3-pro-preview for complex reasoning task
export async function analyzeMessage(message: string, historySignatures: ScamSignature[] = []): Promise<ScamAnalysis> {
  const intensity = apiStatus.currentIntensity;

  return withRetry(async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: message,
      config: {
        responseMimeType: "application/json",
        systemInstruction: HONEY_POT_SYSTEM_PROMPT,
        tools: [{ googleSearch: {} }],
        thinkingConfig: { thinkingBudget: intensity === 'deep' ? 8000 : 2000 }
      }
    });

    const data = safeJsonParse(response.text || "{}");
    const groundingSources: GroundingSource[] = [];

    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web) {
          groundingSources.push({
            title: chunk.web.title || "Defense Reference",
            uri: chunk.web.uri,
            type: 'web'
          });
        }
      });
    }

    const confMap: Record<string, number> = { high: 0.98, medium: 0.75, low: 0.45 };

    const analysis: ScamAnalysis = {
      isScam: !!data.is_scam,
      confidence: confMap[data.confidence_level?.toLowerCase()] || 0.5,
      scamType: data.scam_type || "General Analysis",
      channel: 'text',
      threatLevel: data.is_scam ? (data.confidence_level === 'high' ? 'High' : 'Medium') : 'Low',
      summary: data.reasoning || "Analysis complete.",
      safetyAlert: data.is_scam ? `Detection: Suspicious ${data.scam_type} pattern.` : "Clear.",
      extractedInfo: {
        upiIds: [],
        bankDetails: [],
        ifscCodes: [],
        phoneNumbers: [],
        links: (data.extracted_links || []).map((l: string) => ({ value: l, confidence: 95, timestamp: Date.now() })),
        cryptoWallets: [],
        fakeIdentities: []
      },
      killChainStage: data.is_scam ? 'Exploitation' : 'Delivery',
      fingerprint: {
        primaryHandle: '',
        primaryPhone: '',
        primaryLink: data.extracted_links?.[0] || '',
        category: data.scam_type || "Fraud"
      },
      recommendedActions: [data.recommended_action || "Stay vigilant."],
      groundingSources: groundingSources
    };

    if (analysis.isScam) {
      analysis.guardianGuidance = await generateGuardianGuidance(analysis);
    }

    return analysis;
  });
}

