const App: React.FC = () => {
  const [logs, setLogs] = useState<IntelligenceLog[]>([]);
  const [latestAnalysis, setLatestAnalysis] = useState<{message: string, analysis: IntelligenceLog, sessionId: string} | null>(null);
  const [view, setView] = useState<'home' | 'intelligence' | 'warroom' | 'multimedia' | 'api'>('home');
  const [activeAlert, setActiveAlert] = useState<any>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showTutor, setShowTutor] = useState(false);
  const [showTour, setShowTour] = useState(true);
  const [seniorMode, setSeniorMode] = useState(false);

  const mainInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (seniorMode) {
      document.body.classList.add('senior-mode');
    } else {
      document.body.classList.remove('senior-mode');
    }
  }, [seniorMode]);

  const handleManualAnalyze = async (message: string) => {
    if (!message.trim()) return;
    setIsAnalyzing(true);
    setView('home');
    try {
      const result = await analyzeMessage(message);
      handleAnalysisComplete(message, result);

      if (seniorMode && result.isScam) {
        // Automatically announce scam to senior/blind users
        playVoiceWarning(result.safetyAlert);
      }
    } catch (e: any) {
      console.error(e);
      setActiveAlert({
        level: 'Critical',
        message: 'Analysis Node Timeout',
        details: 'The National Defense Grid is under heavy load. Switching to local heuristic scan.'
      });
    } finally {
      setIsAnalyzing(false);
    }
  };

  const playVoiceWarning = async (text: string) => {
    try {
      const audioBuffer = await generateSpeech(text, 'Kore');
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.start();
    } catch (err) {
      console.error("Auto-voice warning failed", err);
    }
  };

  const handleAnalysisComplete = (message: string, analysis: ScamAnalysis) => {
    const sessionId = `BCR-${Date.now()}`;
    const newLog: IntelligenceLog = {
      ...analysis,
      id: sessionId,
      originalMessage: message,
      timestamp: Date.now(),
      status: 'Open',
      linkedCaseIds: [],
      operationalRequests: [],
      governance: {
        privacyScore: 98,
        evidenceIntegrityHash: `SHA-${Math.random().toString(16).substring(2, 10).toUpperCase()}`,
        ethicsChecklist: { confirmed: true },
        legalStanding: analysis.isScam ? 'Verified Threat' : 'Investigation',
        auditLog: []
      },
      messages: analysis.isScam ? [{ role: 'scammer', content: message, timestamp: Date.now() }] : []
    };

    setLogs(prev => [newLog, ...prev]);
    setLatestAnalysis({ message, analysis: newLog, sessionId });

    if (analysis.isScam) {
      setActiveAlert({
        level: analysis.threatLevel,
        message: analysis.safetyAlert,
        details: "Honeypot protocol initiated. Intelligence extraction active."
      });
    }
  };

  const runSimulation = (count: number) => {
    const newSimulatedLogs = Array.from({ length: count }).map((_, i) => 
      generateSimulatedCase(`SIM-${Date.now()}-${i}`)
    );
    setLogs(prev => [...newSimulatedLogs, ...prev]);
    setView('intelligence');
  };

  const updateIntelFromHoneypot = (sessionId: string, info: ExtractedInfo) => {
    setLogs(prev => prev.map(l => {
      if (l.id === sessionId) {
        return {
          ...l,
          extractedInfo: {
            ...l.extractedInfo,
            upiIds: [...l.extractedInfo.upiIds, ...info.upiIds],
            bankDetails: [...l.extractedInfo.bankDetails, ...info.bankDetails]
          }
        };
      }
      return l;
    }));
  };

  const runDemo = () => {
    const demo = "URGENT: This is Mumbai Police Cyber Cell. Your Aadhaar is linked to a money laundering case. Pay ₹50,000 security deposit immediately to UPI: police.verify@okaxis or face arrest.";
    if (mainInputRef.current) mainInputRef.current.value = demo;
    handleManualAnalyze(demo);
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 selection:bg-blue-600/10">
      <GlobalNewsTicker />

      {showTour && <OnboardingTour activeView={view} onViewChange={(v) => setView(v)} onComplete={() => setShowTour(false)} />}

      <header role="banner" className="bg-white/80 backdrop-blur-md px-8 py-4 flex items-center justify-between sticky top-10 z-[60] border-b border-slate-200 shadow-sm">
        <div className="flex items-center space-x-4">
          <div className="bg-slate-950 p-2.5 rounded-2xl shadow-lg">
            <svg className="w-6 h-6 text-blue-500" aria-hidden="true" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
          </div>
          <button onClick={() => setView('home')} aria-label="Go to Home" className="text-left focus:outline-none">
            <h1 className="text-2xl font-black tracking-tighter text-slate-950 uppercase">Bharat <span className="text-blue-600">Cyber</span> Rakshak</h1>
          </button>
        </div>

        <nav role="navigation" aria-label="Main Menu" className="hidden lg:flex items-center bg-slate-100 p-1 rounded-full border border-slate-200">
           <NavBtn active={view === 'home'} onClick={() => setView('home')} label="Interceptor" />
           <NavBtn active={view === 'multimedia'} onClick={() => setView('multimedia')} label="Multimedia" />
           <NavBtn active={view === 'intelligence'} onClick={() => setView('intelligence')} label="Intelligence" />
           <NavBtn active={view === 'warroom'} onClick={() => setView('warroom')} label="War Room" />
           <NavBtn active={view === 'api'} onClick={() => setView('api')} label="API Hub" />
        </nav>

        <div className="flex items-center space-x-6">
           <button 
             onClick={() => setSeniorMode(!seniorMode)}
             className={`flex items-center space-x-2 px-4 py-2 rounded-xl border transition-all ${seniorMode ? 'bg-blue-600 border-blue-600 text-white' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}
             aria-pressed={seniorMode}
           >
             <span className="text-lg" aria-hidden="true">👵</span>
             <span className="text-[10px] font-black uppercase tracking-widest">{seniorMode ? 'Senior Mode ON' : 'Senior Mode'}</span>
           </button>
           <div className="flex items-center space-x-3">
              <div className={`w-3 h-3 rounded-full ${apiStatus.isThrottled ? 'bg-amber-500' : 'bg-green-500'}`} />
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Node_Active</span>
           </div>
        </div>
      </header>

      <SafetyBanner alert={activeAlert} onDismiss={() => setActiveAlert(null)} />

      <main id="main-content" className="flex-1" role="main">
        {view === 'home' ? (
          <div className="animate-in fade-in duration-700">
             <section className="hero-pattern py-32 px-8 text-center text-white" aria-labelledby="hero-title">
                <div className="max-w-4xl mx-auto space-y-8">
                   <h2 id="hero-title" className="text-6xl font-black tracking-tighter leading-none">Sovereign Protection <br/>For Indian Citizens</h2>
                   <p className="text-xl text-blue-100/80 font-medium max-w-2xl mx-auto">AI-powered interception of KYC, UPI, and Digital Arrest frauds.</p>

                   <div className="pt-12 space-y-8">
                      <div className="max-w-3xl mx-auto bg-white rounded-[3rem] p-3 shadow-2xl flex flex-col md:flex-row gap-2 ring-8 ring-white/10">
                        <label htmlFor="interceptor-input" className="sr-only">Paste suspicious message</label>
                        <input 
                          id="interceptor-input"
                          ref={mainInputRef}
                          className="flex-1 px-8 py-5 text-slate-900 placeholder:text-slate-400 text-lg outline-none rounded-full font-medium"
                          placeholder="Paste a suspicious SMS, UPI link, or Aadhaar alert..."
                          onKeyDown={(e) => e.key === 'Enter' && handleManualAnalyze(e.currentTarget.value)}
                        />
                        <button onClick={() => mainInputRef.current && handleManualAnalyze(mainInputRef.current.value)}
                          disabled={isAnalyzing}
                          aria-busy={isAnalyzing}
                          className="px-12 py-5 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white rounded-[2.5rem] font-black text-lg transition-all shadow-xl active:scale-95 glow-cobalt"
                        >
                          {isAnalyzing ? 'SCANNING...' : 'INTERCEPT'}
                        </button>
                      </div>

                      <button 
                        onClick={runDemo} 
                        aria-label="Run presentation demo"
                        className="group relative px-12 py-5 bg-slate-950 border-2 border-blue-500/50 rounded-full hover:border-blue-500 transition-all shadow-2xl"
                      >
                        <div className="relative flex items-center space-x-4">
                          <div className="w-3 h-3 bg-blue-500 rounded-full animate-ping"></div>
                          <span className="text-sm font-black uppercase tracking-[0.4em] text-blue-400 group-hover:text-white">Run Presentation Demo</span>
                        </div>
                      </button>
                   </div>
                </div>
             </section>

             {latestAnalysis && (
               <div className="container mx-auto px-8 max-w-6xl py-20 space-y-20 animate-in slide-in-from-bottom-10">
                 <ResultPanel analysis={latestAnalysis.analysis} seniorMode={seniorMode} onClose={() => setLatestAnalysis(null)} />
                 {latestAnalysis.analysis.isScam && (
                    <div className="h-[800px]" aria-label="Active Honeypot Session">
                      <BaitSession 
                        sessionId={latestAnalysis.sessionId}
                        initialMessages={latestAnalysis.analysis.messages}
                        onMessagesUpdate={(msgs) => setLogs(prev => prev.map(l => l.id === latestAnalysis.sessionId ? { ...l, messages: msgs } : l))}
                        onIntelExtracted={(info) => updateIntelFromHoneypot(latestAnalysis.sessionId, info)}
                      />
                    </div>
                 )}
               </div>
             )}
          </div>
        ) : view === 'intelligence' ? (
          <div className="container mx-auto px-8 py-16 max-w-7xl"><IntelligenceDashboard logs={logs} /></div>
        ) : view === 'warroom' ? (
          <div className="container mx-auto px-8 py-16 max-w-7xl"><WarRoom logs={logs} onRunSimulation={runSimulation} /></div>
