          <div className="container mx-auto px-8 py-16 max-w-7xl"><ApiDeveloperHub /></div>
        ) : (
          <div className="container mx-auto px-8 py-16 max-w-7xl space-y-20 animate-in fade-in">
             <LiveShield onAlert={(analysis) => handleAnalysisComplete("LIVE_VOICE_INTERCEPT", analysis)} />
