import React, { useState } from 'react';
import { IntelligenceLog, GroundingSource } from '../types';
import { findLocalCyberCell, generateSpeech } from '../services/geminiService';
import ForensicLab from './ForensicLab';
import KillChainVisualizer from './KillChainVisualizer';

interface Props {
  analysis: IntelligenceLog;
  seniorMode?: boolean;
  onClose: () => void;
}

const ResultPanel: React.FC<Props> = ({ analysis, seniorMode, onClose }) => {
  const [localAuthorities, setLocalAuthorities] = useState<GroundingSource[]>([]);
  const [isLocating, setIsLocating] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);

  const isScam = analysis.isScam;
  const guardian = analysis.guardianGuidance;
  const webGrounding = (analysis.groundingSources || []).filter(s => s.type === 'web');

  const handleLocateAuthorities = async () => {
    setIsLocating(true);
    try {
      navigator.geolocation.getCurrentPosition(async (pos) => {
        const results = await findLocalCyberCell(pos.coords.latitude, pos.coords.longitude);
        setLocalAuthorities(results);
        setIsLocating(false);
      }, (err) => {
        console.error(err);
        setIsLocating(false);
        alert("Location access denied. Please allow location to find authorities.");
      });
    } catch (e) {
      console.error(e);
      setIsLocating(false);
    }
  };

  const speakReport = async () => {
    if (isSpeaking) return;
    setIsSpeaking(true);
    try {
      const textToSpeak = `${isScam ? 'Scam Detected.' : 'This message is safe.'} ${guardian?.user_alert || analysis.summary}. Recommended steps: ${guardian?.what_to_do_now.join('. ')}`;
      const audioBuffer = await generateSpeech(textToSpeak, 'Kore');
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.onended = () => setIsSpeaking(false);
      source.start();
    } catch (err) {
      console.error("Speech synthesis failed", err);
      setIsSpeaking(false);
    }
  };

  return (
    <div className="space-y-12 animate-in slide-in-from-bottom-10 duration-700" role="region" aria-label="Scam Analysis Result">
      {/* Primary Verdict Card */}
      <div className="bg-white rounded-[4rem] border border-slate-200 shadow-2xl overflow-hidden">
        <div className={`px-12 py-12 flex flex-col md:flex-row items-center justify-between gap-8 ${
          isScam ? 'bg-red-50' : 'bg-emerald-50'
        }`}>
          <div className="flex items-center space-x-8">
            <div className={`w-24 h-24 rounded-[2.5rem] flex items-center justify-center text-4xl shadow-xl ${
              isScam ? 'bg-red-600 text-white' : 'bg-emerald-600 text-white'
            }`}>
              {isScam ? '🚨' : '🛡️'}
            </div>
            <div className="space-y-2">
              <h2 className={`text-5xl font-black uppercase tracking-tighter ${
                isScam ? 'text-red-700' : 'text-emerald-700'
              }`} id="analysis-verdict">
                {isScam ? 'SCAM IDENTIFIED' : 'SECURE_SENDER'}
              </h2>
              <p className="text-slate-500 font-black uppercase text-xs tracking-[0.3em]">Verified via Sovereign AI Defense Grid</p>
            </div>
          </div>

          <div className="flex flex-col items-center md:items-end space-y-4">
            <button 
              onClick={speakReport}
              disabled={isSpeaking}
              className={`flex items-center space-x-3 px-8 py-3 rounded-2xl font-black uppercase text-xs tracking-widest transition-all ${isSpeaking ? 'bg-slate-100 text-slate-400' : 'bg-blue-600 text-white hover:bg-blue-500 shadow-lg'}`}
              aria-label="Listen to report out loud"
            >
              <span className="text-lg">{isSpeaking ? '🔊' : '🔈'}</span>
              <span>{isSpeaking ? 'Reading Report...' : 'Listen to Report'}</span>
            </button>
            <div className="text-right">
              <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Neural Confidence</div>
              <div className="text-4xl font-black text-slate-900">{(analysis.confidence * 100).toFixed(1)}%</div>
            </div>
          </div>
        </div>

        <div className="p-12 grid grid-cols-1 lg:grid-cols-2 gap-12">
          <div className="space-y-8">
            <div className="space-y-4" role="alert" aria-live="polite">
              <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.3em]">Guardian Protocol Advice</h4>
              <p className="text-2xl font-black text-slate-900 leading-tight">{guardian?.user_alert}</p>
              <div className="space-y-3 pt-4">
                {(guardian?.what_to_do_now || []).map((step, i) => (
                  <div key={i} className="flex items-center space-x-4 bg-slate-50 p-5 rounded-2xl border border-slate-200">
                    <div className="w-8 h-8 rounded-xl bg-slate-900 text-white flex items-center justify-center font-black text-sm">{i + 1}</div>
                    <span className="text-sm font-bold text-slate-700">{step}</span>
                  </div>
                ))}
              </div>
            </div>

            {isScam && (
              <div className="space-y-4 pt-6 border-t border-slate-100">
                <div className="flex justify-between items-center">
                  <h4 className="text-[10px] font-black text-emerald-600 uppercase tracking-[0.3em]">Localized Authority Links</h4>
                  {!localAuthorities.length && (
                    <button onClick={handleLocateAuthorities} disabled={isLocating} className="text-[10px] font-black bg-emerald-600 text-white px-5 py-2.5 rounded-full uppercase tracking-widest transition-all hover:scale-105 disabled:opacity-50">
                      {isLocating ? 'Locating...' : 'Find Nearest Cyber Cell'}
                    </button>
                  )}
                </div>
                <div className="grid grid-cols-1 gap-4">
                  {localAuthorities.map((auth, i) => (
                    <div key={i} className="bg-emerald-50 border border-emerald-100 p-6 rounded-[2.5rem] flex items-center justify-between">
                      <div className="space-y-1">
                        <p className="text-xs font-black text-emerald-900 uppercase">{auth.title}</p>
                        <p className="text-[10px] text-emerald-700 font-bold opacity-70 truncate max-w-xs">{auth.address}</p>
                      </div>
                      <a href={auth.uri} target="_blank" className="px-6 py-3 bg-white text-emerald-600 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-sm">Navigate</a>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          <div className="space-y-8">
             <div className="space-y-4">
                <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.3em]">Verified Intelligence Citations</h4>
                <div className="grid grid-cols-1 gap-4">
                  {webGrounding.map((source, i) => (
                    <a key={i} href={source.uri} target="_blank" className="p-5 bg-blue-50 border border-blue-100 rounded-[2.5rem] flex items-center justify-between group hover:bg-white transition-all hover:shadow-xl">
                      <div className="flex items-center space-x-4 overflow-hidden">
                        <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center shrink-0">
                          <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                        </div>
                        <div className="overflow-hidden">
                          <p className="text-xs font-black text-slate-900 uppercase tracking-tight truncate">{source.title}</p>
                          <p className="text-[10px] text-blue-600 font-bold mt-1">{new URL(source.uri).hostname}</p>
                        </div>
                      </div>
                      <svg className="w-5 h-5 text-blue-600 opacity-30 group-hover:opacity-100" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" /></svg>
                    </a>
                  ))}
                  {!webGrounding.length && <p className="text-sm font-bold text-slate-400 italic">Correlating global search data...</p>}
                </div>
             </div>

             <div className="bg-slate-950 rounded-[2.5rem] p-8 text-white space-y-4 relative overflow-hidden">
                <div className="relative z-10">
                   <h4 className="text-[10px] font-black text-blue-500 uppercase tracking-[0.4em] mb-2">Honeypot Active</h4>
                   <h3 className="text-xl font-black tracking-tight">Rakshak Agent BCR-S01 engaged.</h3>
                   <p className="text-[11px] text-slate-400 leading-relaxed">System is acting as a confused victim to collect scammer's bank accounts and technical markers automatically.</p>
                </div>
             </div>
          </div>
        </div>
      </div>

      {/* Advanced Forensic Drilldown */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
        <div className="lg:col-span-4 h-full">
           <KillChainVisualizer analysis={analysis} />
        </div>
        <div className="lg:col-span-8 h-full">
           <ForensicLab analysis={analysis} />
        </div>
      </div>

      <div className="flex justify-center pb-12">
        <button onClick={onClose} className="px-16 py-5 bg-white border border-slate-200 text-slate-500 hover:text-slate-950 rounded-[2rem] font-black uppercase text-xs tracking-[0.3em] transition-all hover:shadow-2xl">
          Terminate Case Review
        </button>
      </div>
