import ResultPanel from './components/ResultPanel';
import LiveShield from './components/LiveShield';
import VideoScanner from './components/VideoScanner';
import SafetyBanner from './components/SafetyBanner';
import BaitSession from './components/BaitSession';
import WarRoom from './components/WarRoom';
import RakshakTutor from './components/RakshakTutor';
import OnboardingTour from './components/OnboardingTour';
import ApiDeveloperHub from './components/ApiDeveloperHub';
import { ScamAnalysis, IntelligenceLog, ExtractedInfo } from './types';
import { analyzeMessage, apiStatus, generateSpeech } from './services/geminiService';
import { generateSimulatedCase } from './utils/scamGenerator';

interface NavBtnProps {
  active: boolean;
  onClick: () => void;
  label: string;
  icon: string;
}

function NavBtn({ active, onClick, label, icon }: NavBtnProps) {
  return (
    <button 
      onClick={onClick} 
      aria-pressed={active}
      className={`px-6 py-3 rounded-2xl flex items-center space-x-3 transition-all ${
        active ? 'bg-blue-600 text-white shadow-xl scale-105' : 'text-slate-500 hover:text-slate-900 hover:bg-white'
      }`}
    >
      <span className="text-xl" aria-hidden="true">{icon}</span>
      <span className="text-xs font-black uppercase tracking-widest">{label}</span>
    </button>
  );
}

const QuickExample = ({ label, text, onClick }: { label: string, text: string, onClick: (t: string) => void }) => (
  <button 
    onClick={() => onClick(text)}
    className="px-4 py-2 bg-white/10 hover:bg-white/20 border border-white/20 rounded-xl text-[10px] font-black uppercase tracking-widest text-white transition-all hover:scale-105 active:scale-95"
  >
    {label}
  </button>
);

const App: React.FC = () => {
  const [logs, setLogs] = useState<IntelligenceLog[]>([]);
  const [latestAnalysis, setLatestAnalysis] = useState<{message: string, analysis: IntelligenceLog, sessionId: string} | null>(null);
  const [view, setView] = useState<'home' | 'intelligence' | 'warroom' | 'multimedia' | 'api'>('home');
  const [activeAlert, setActiveAlert] = useState<any>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showTutor, setShowTutor] = useState(false);
  const [showTour, setShowTour] = useState(true);
  const [seniorMode, setSeniorMode] = useState(false);

  const mainInputRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (seniorMode) {
      document.body.classList.add('senior-mode');
    } else {
      document.body.classList.remove('senior-mode');
    }
  }, [seniorMode]);

  const handleManualAnalyze = async (message: string) => {
    if (!message.trim()) return;
    setIsAnalyzing(true);
    setView('home');
    try {
      const result = await analyzeMessage(message);
      handleAnalysisComplete(message, result);

      if (seniorMode && result.isScam) {
        playVoiceWarning(result.safetyAlert);
      }
    } catch (e: any) {
      console.error(e);
      setActiveAlert({
        level: 'Critical',
        message: 'Grid Connection Error',
        details: 'The Cyber Defense Grid is currently under maintenance. Please try again in a few minutes.'
      });
    } finally {
      setIsAnalyzing(false);
    }
  };

  const playVoiceWarning = async (text: string) => {
    try {
      const audioBuffer = await generateSpeech(text, 'Kore');
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.start();
    } catch (err) {
      console.error("Auto-voice warning failed", err);
    }
  };

  const handleAnalysisComplete = (message: string, analysis: ScamAnalysis) => {
    const sessionId = `BCR-${Date.now()}`;
    const newLog: IntelligenceLog = {
      ...analysis,
      id: sessionId,
      originalMessage: message,
      timestamp: Date.now(),
      status: 'Open',
      linkedCaseIds: [],
      operationalRequests: [],
      governance: {
        privacyScore: 98,
        evidenceIntegrityHash: `SHA-${Math.random().toString(16).substring(2, 10).toUpperCase()}`,
        ethicsChecklist: { confirmed: true },
        legalStanding: analysis.isScam ? 'Verified Threat' : 'Investigation',
        auditLog: []
      },
      messages: analysis.isScam ? [{ role: 'scammer', content: message, timestamp: Date.now() }] : []
    };

    setLogs(prev => [newLog, ...prev]);
    setLatestAnalysis({ message, analysis: newLog, sessionId });

    if (analysis.isScam) {
      setActiveAlert({
        level: analysis.threatLevel,
        message: analysis.safetyAlert,
        details: "AI Agent 'Rakshak' is now engaging the scammer."
      });
    }
  };

  const handleQuickDemo = (text: string) => {
    if (mainInputRef.current) {
      mainInputRef.current.value = text;
      handleManualAnalyze(text);
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 selection:bg-blue-600/10">
      {showTour && <OnboardingTour activeView={view} onViewChange={(v) => setView(v)} onComplete={() => setShowTour(false)} />}

      <header role="banner" className="bg-white/90 backdrop-blur-xl px-8 py-4 flex items-center justify-between sticky top-0 z-[100] border-b border-slate-200 shadow-sm">
        <div className="flex items-center space-x-4">
          <div className="bg-slate-950 p-2.5 rounded-2xl shadow-lg">
            <svg className="w-6 h-6 text-blue-500" aria-hidden="true" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
          </div>
          <button onClick={() => setView('home')} aria-label="Go to Home" className="text-left focus:outline-none">
            <h1 className="text-2xl font-black tracking-tighter text-slate-950 uppercase">Bharat <span className="text-blue-600">Cyber</span> Rakshak</h1>
          </button>
        </div>

        <nav role="navigation" aria-label="Main Menu" className="hidden lg:flex items-center space-x-2 bg-slate-100 p-1.5 rounded-3xl border border-slate-200">
           <NavBtn active={view === 'home'} onClick={() => setView('home')} label="Check" icon="🔍" />
           <NavBtn active={view === 'multimedia'} onClick={() => setView('multimedia')} label="Multimedia" icon="📷" />
           <NavBtn active={view === 'intelligence'} onClick={() => setView('intelligence')} label="Stats" icon="📊" />
           <NavBtn active={view === 'warroom'} onClick={() => setView('warroom')} label="War Room" icon="⚔️" />
        </nav>

        <div className="flex items-center space-x-4">
           <button 
             onClick={() => setSeniorMode(!seniorMode)}
             className={`flex items-center space-x-2 px-6 py-2.5 rounded-2xl border transition-all ${seniorMode ? 'bg-orange-600 border-orange-600 text-white scale-110 shadow-lg' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}
             aria-pressed={seniorMode}
           >
             <span className="text-xl" aria-hidden="true">👵</span>
             <span className="text-xs font-black uppercase tracking-widest">{seniorMode ? 'Easy Mode ON' : 'Easy Mode'}</span>
           </button>
        </div>
      </header>

      <SafetyBanner alert={activeAlert} onDismiss={() => setActiveAlert(null)} />

      <main id="main-content" className="flex-1" role="main">
        {view === 'home' ? (
          <div className="animate-in fade-in duration-700">
             <section className="hero-pattern py-24 px-8 text-center text-white" aria-labelledby="hero-title">
                <div className="max-w-4xl mx-auto space-y-10">
                   <h2 id="hero-title" className="text-7xl font-black tracking-tighter leading-none">
                     Paste Your <span className="text-blue-400">Suspicious</span> <br/>Message Below
                   </h2>

                   <div className="pt-8 space-y-10">
                      <div className="max-w-3xl mx-auto bg-white rounded-[3rem] p-4 shadow-2xl flex flex-col gap-4 ring-[12px] ring-white/10">
                        <label htmlFor="interceptor-input" className="sr-only">Paste the text you received here</label>
                        <textarea 
                          id="interceptor-input"
                          ref={mainInputRef}
                          className="w-full h-40 px-8 py-6 text-slate-900 placeholder:text-slate-300 text-2xl outline-none rounded-[2rem] font-bold bg-slate-50 border-2 border-slate-100 focus:border-blue-500 transition-all resize-none"
                          placeholder="Paste the SMS or link here..."
                        />
                        <button 
                          onClick={() => mainInputRef.current && handleManualAnalyze(mainInputRef.current.value)}
                          disabled={isAnalyzing}
                          aria-busy={isAnalyzing}
                          className="w-full py-6 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white rounded-[2rem] font-black text-2xl transition-all shadow-2xl active:scale-95 glow-cobalt flex items-center justify-center space-x-4"
                        >
                          {isAnalyzing ? (
                            <>
                              <div className="w-6 h-6 border-4 border-white border-t-transparent rounded-full animate-spin" />
                              <span>ANALYZING...</span>
                            </>
                          ) : (
                            <>
                              <span className="text-3xl">🛡️</span>
                              <span>START PROTECTION</span>
                            </>
                          )}
                        </button>
                      </div>

                      <div className="flex flex-wrap justify-center gap-3 pt-4">
                        <span className="text-xs font-black uppercase tracking-widest opacity-60 w-full mb-2">Try an Example:</span>
                        <QuickExample 
                          label="Bank SMS Scam" 
                          text="ALERT: Your SBI Account is blocked for KYC. Call 9988776655 to verify. Failing which your account will be closed." 
                          onClick={handleQuickDemo}
                        />
                        <QuickExample 
                          label="Police Threat" 
                          text="This is Mumbai Police. Your Aadhaar is linked to a drug parcel. Pay ₹25,000 for verification or face arrest." 
                          onClick={handleQuickDemo}
                        />
                        <QuickExample 
                          label="Gift Card Fraud" 
                          text="Congratulations! You won ₹1 Crore from KBC. Pay ₹5,000 as processing fee to UPI: rewards.kbc@okaxis" 
                          onClick={handleQuickDemo}
                        />
                      </div>
                   </div>
                </div>
             </section>

             {latestAnalysis && (
               <div className="container mx-auto px-8 max-w-6xl py-20 space-y-20 animate-in slide-in-from-bottom-10">
                 <ResultPanel analysis={latestAnalysis.analysis} seniorMode={seniorMode} onClose={() => setLatestAnalysis(null)} />
                 {latestAnalysis.analysis.isScam && (
                    <div className="h-[800px] border-4 border-slate-950 rounded-[4rem] overflow-hidden shadow-2xl" aria-label="Live Honeypot: Scammer vs AI">
                      <BaitSession 
                        sessionId={latestAnalysis.sessionId}
                        initialMessages={latestAnalysis.analysis.messages}
                        onMessagesUpdate={(msgs) => setLogs(prev => prev.map(l => l.id === latestAnalysis.sessionId ? { ...l, messages: msgs } : l))}
                        onIntelExtracted={(info) => {
                          setLogs(prev => prev.map(l => {
                            if (l.id === latestAnalysis.sessionId) {
                              return {
                                ...l,
                                extractedInfo: {
                                  ...l.extractedInfo,
                                  upiIds: [...l.extractedInfo.upiIds, ...info.upiIds]
                                }
                              };
                            }
                            return l;
                          }));
                        }}
                      />
                    </div>
                 )}
               </div>
             )}
          </div>
        ) : view === 'intelligence' ? (
          <div className="container mx-auto px-8 py-16 max-w-7xl"><IntelligenceDashboard logs={logs} /></div>
        ) : view === 'warroom' ? (
          <div className="container mx-auto px-8 py-16 max-w-7xl"><WarRoom logs={logs} onRunSimulation={(count) => {
            const sims = Array.from({ length: count }).map((_, i) => generateSimulatedCase(`SIM-${Date.now()}-${i}`));
            setLogs(prev => [...sims, ...prev]);
            setView('intelligence');
          }} /></div>
        ) : (
          <div className="container mx-auto px-8 py-16 max-w-7xl space-y-20 animate-in fade-in">
             <LiveShield onAlert={(analysis) => handleAnalysisComplete("LIVE_VOICE_INTERCEPT", analysis)} />
             <VideoScanner />
          </div>
        )}
      </main>

      <button 
        onClick={() => setShowTutor(true)} 
        aria-label="Open Rakshak Mitra Help"
        className="fixed bottom-10 left-10 z-[150] w-20 h-20 bg-slate-950 text-white rounded-[2rem] flex items-center justify-center shadow-2xl hover:scale-110 transition-all group border-4 border-blue-500"
      >
        <span className="text-4xl group-hover:animate-bounce" aria-hidden="true">🧑‍🏫</span>
      </button>

      {showTutor && <RakshakTutor onClose={() => setShowTutor(false)} />}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { IntelligenceLog, GroundingSource } from '../types';
import { findLocalCyberCell, generateSpeech } from '../services/geminiService';
import ForensicLab from './ForensicLab';
import KillChainVisualizer from './KillChainVisualizer';

interface Props {
  analysis: IntelligenceLog;
  seniorMode?: boolean;
  onClose: () => void;
}

const ResultPanel: React.FC<Props> = ({ analysis, seniorMode, onClose }) => {
  const [localAuthorities, setLocalAuthorities] = useState<GroundingSource[]>([]);
  const [isLocating, setIsLocating] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);

  const isScam = analysis.isScam;
  const guardian = analysis.guardianGuidance;
  const webGrounding = (analysis.groundingSources || []).filter(s => s.type === 'web');

  const handleLocateAuthorities = async () => {
    setIsLocating(true);
    try {
      navigator.geolocation.getCurrentPosition(async (pos) => {
        const results = await findLocalCyberCell(pos.coords.latitude, pos.coords.longitude);
        setLocalAuthorities(results);
        setIsLocating(false);
      }, (err) => {
        console.error(err);
        setIsLocating(false);
        alert("Please allow location access to find the nearest Cyber Police station.");
      });
    } catch (e) {
      console.error(e);
      setIsLocating(false);
    }
  };

  const speakReport = async () => {
    if (isSpeaking) return;
    setIsSpeaking(true);
    try {
      const textToSpeak = `${isScam ? 'Alert: This is a scam message.' : 'Good news: This message appears safe.'} ${guardian?.user_alert || analysis.summary}. I recommend you: ${guardian?.what_to_do_now.join('. ')}`;
      const audioBuffer = await generateSpeech(textToSpeak, 'Kore');
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.onended = () => setIsSpeaking(false);
      source.start();
    } catch (err) {
      console.error("Speech synthesis failed", err);
      setIsSpeaking(false);
    }
  };

  return (
    <div className="space-y-12 animate-in slide-in-from-bottom-10 duration-700" role="region" aria-label="Scam Analysis Result">
      <div className={`rounded-[4rem] border-8 shadow-2xl overflow-hidden ${
          isScam ? 'bg-red-50 border-red-600' : 'bg-emerald-50 border-emerald-600'
        }`}>
        <div className="px-12 py-16 flex flex-col lg:flex-row items-center justify-between gap-12">
          <div className="flex flex-col lg:flex-row items-center gap-10 text-center lg:text-left">
            <div className={`w-32 h-32 rounded-[3rem] flex items-center justify-center text-6xl shadow-2xl ${
              isScam ? 'bg-red-600 text-white' : 'bg-emerald-600 text-white'
            }`}>
              {isScam ? '⚠️' : '✅'}
            </div>
            <div className="space-y-3">
              <h2 className={`text-6xl font-black uppercase tracking-tighter ${
                isScam ? 'text-red-700' : 'text-emerald-700'
              }`}>
                {isScam ? 'STOP! IT\'S A SCAM' : 'MESSAGE IS SAFE'}
              </h2>
              <p className="text-slate-600 font-bold uppercase text-lg tracking-widest">SCANNED BY NATIONAL AI DEFENSE</p>
            </div>
          </div>

          <div className="flex flex-col items-center lg:items-end gap-6">
            <button 
              onClick={speakReport}
              disabled={isSpeaking}
              className={`flex items-center space-x-4 px-12 py-6 rounded-[2.5rem] font-black uppercase text-xl transition-all ${isSpeaking ? 'bg-slate-200 text-slate-400' : 'bg-slate-950 text-white hover:bg-slate-800 shadow-2xl scale-110 active:scale-95'}`}
              aria-label="Click to hear this report spoken out loud"
            >
              <span className="text-3xl">{isSpeaking ? '🔊' : '🔈'}</span>
              <span>{isSpeaking ? 'Reading...' : 'Listen to Result'}</span>
            </button>
            <div className="text-center lg:text-right">
              <div className="text-xs font-black text-slate-400 uppercase tracking-widest mb-1">AI Confidence Score</div>
              <div className="text-5xl font-black text-slate-900">{(analysis.confidence * 100).toFixed(0)}%</div>
            </div>
          </div>
        </div>

        <div className="p-12 grid grid-cols-1 lg:grid-cols-2 gap-12 bg-white rounded-t-[4rem]">
          <div className="space-y-10">
            <div className="space-y-6" role="alert" aria-live="polite">
              <h4 className="text-xs font-black text-blue-600 uppercase tracking-[0.4em]">What you should do now:</h4>
              <p className="text-3xl font-black text-slate-900 leading-tight">{guardian?.user_alert}</p>
              <div className="space-y-4 pt-4">
                {(guardian?.what_to_do_now || []).map((step, i) => (
                  <div key={i} className="flex items-center space-x-6 bg-slate-50 p-6 rounded-3xl border-2 border-slate-100 shadow-sm">
                    <div className="w-12 h-12 shrink-0 rounded-2xl bg-slate-950 text-white flex items-center justify-center font-black text-xl">{i + 1}</div>
                    <span className="text-xl font-bold text-slate-800">{step}</span>
                  </div>
                ))}
              </div>
            </div>

            {isScam && (
              <div className="space-y-6 pt-10 border-t-2 border-slate-100">
                <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
                  <h4 className="text-xs font-black text-emerald-600 uppercase tracking-[0.4em]">Find Police Help:</h4>
                  {!localAuthorities.length && (
                    <button onClick={handleLocateAuthorities} disabled={isLocating} className="text-sm font-black bg-emerald-600 text-white px-8 py-4 rounded-2xl uppercase tracking-widest transition-all hover:bg-emerald-500 shadow-xl disabled:opacity-50">
                      {isLocating ? 'Locating...' : 'Find Nearest Cyber Cell'}
                    </button>
                  )}
                </div>
                <div className="grid grid-cols-1 gap-4">
                  {localAuthorities.map((auth, i) => (
                    <div key={i} className="bg-emerald-50 border-2 border-emerald-100 p-6 rounded-3xl flex items-center justify-between">
                      <div className="space-y-1">
                        <p className="text-lg font-black text-emerald-900 uppercase">{auth.title}</p>
                        <p className="text-sm text-emerald-700 font-bold opacity-80">{auth.address}</p>
                      </div>
                      <a href={auth.uri} target="_blank" className="px-8 py-4 bg-white text-emerald-600 rounded-2xl text-xs font-black uppercase tracking-widest shadow-lg hover:bg-emerald-500 hover:text-white transition-all">Directions</a>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          <div className="space-y-10">
             <div className="space-y-6">
                <h4 className="text-xs font-black text-blue-600 uppercase tracking-[0.4em]">Proof from the Web:</h4>
                <div className="grid grid-cols-1 gap-4">
                  {webGrounding.map((source, i) => (
                    <a key={i} href={source.uri} target="_blank" className="p-6 bg-blue-50 border-2 border-blue-100 rounded-3xl flex items-center justify-between group hover:bg-white transition-all hover:shadow-2xl">
                      <div className="flex items-center space-x-6 overflow-hidden">
                        <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center shrink-0 shadow-lg">
                          <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                        </div>
                        <div className="overflow-hidden">
                          <p className="text-lg font-black text-slate-900 uppercase tracking-tight truncate">{source.title}</p>
                          <p className="text-xs text-blue-600 font-black mt-1 uppercase tracking-widest">{new URL(source.uri).hostname}</p>
                        </div>
                      </div>
                      <svg className="w-6 h-6 text-blue-600 opacity-30 group-hover:opacity-100 transition-opacity" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" /></svg>
                    </a>
                  ))}
                </div>
             </div>

             {isScam && (
               <div className="bg-slate-950 rounded-[3rem] p-10 text-white space-y-6 relative overflow-hidden shadow-2xl">
                  <div className="relative z-10">
                     <div className="flex items-center space-x-3 mb-4">
                        <div className="w-4 h-4 bg-red-600 rounded-full animate-ping" />
                        <h4 className="text-xs font-black text-blue-400 uppercase tracking-[0.5em]">Honeypot protocol active</h4>
                     </div>
                     <h3 className="text-3xl font-black tracking-tight leading-none mb-4">I am engaging this scammer right now.</h3>
                     <p className="text-lg text-slate-400 font-medium leading-relaxed">
                       Don't worry. I am pretending to be a confused user to trap them. Scroll down to see the live chat.
                     </p>
                  </div>
               </div>
             )}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 pt-10">
        <div className="lg:col-span-4"><KillChainVisualizer analysis={analysis} /></div>
        <div className="lg:col-span-8"><ForensicLab analysis={analysis} /></div>
      </div>

      <div className="flex justify-center pb-20">
        <button onClick={onClose} className="px-20 py-8 bg-white border-4 border-slate-950 text-slate-950 hover:bg-slate-950 hover:text-white rounded-[3rem] font-black uppercase text-xl tracking-[0.3em] transition-all hover:shadow-2xl active:scale-95">
          Close Report
        </button>
      </div>
    </div>
  );
};

export default ResultPanel;

import React, { useState, useRef, useEffect } from 'react';
import IntelligenceDashboard from './components/IntelligenceDashboard';
import ResultPanel from './components/ResultPanel';
import LiveShield from './components/LiveShield';
import VideoScanner from './components/VideoScanner';
import SafetyBanner from './components/SafetyBanner';
import BaitSession from './components/BaitSession';
import WarRoom from './components/WarRoom';
import RakshakTutor from './components/RakshakTutor';
import OnboardingTour from './components/OnboardingTour';
import { ScamAnalysis, IntelligenceLog, ExtractedInfo } from './types';
import { analyzeMessage, apiStatus, generateSpeech } from './services/geminiService';
import { generateSimulatedCase } from './utils/scamGenerator';

interface NavBtnProps {
  active: boolean;
  onClick: () => void;
  label: string;
  icon: string;
}

function NavBtn({ active, onClick, label, icon }: NavBtnProps) {
  return (
    <button 
      onClick={onClick} 
      aria-pressed={active}
      className={`px-8 py-3 rounded-2xl flex items-center space-x-3 transition-all border-2 ${
        active 
        ? 'bg-blue-600 border-blue-500 text-white shadow-xl scale-105' 
        : 'bg-white border-slate-100 text-slate-500 hover:text-slate-900 hover:border-slate-300'
      }`}
    >
      <span className="text-2xl" aria-hidden="true">{icon}</span>
      <span className="text-sm font-black uppercase tracking-widest">{label}</span>
    </button>
  );
}

const QuickDemoCard = ({ label, text, icon, onClick }: { label: string, text: string, icon: string, onClick: (t: string) => void }) => (
  <button 
    onClick={() => onClick(text)}
