          tools: [{ googleSearch: {} }]
        }
      });

      const data = safeJsonParse(response.text || "{}");
      const groundingSources: GroundingSource[] = [];
      response.candidates?.[0]?.groundingMetadata?.groundingChunks?.forEach((chunk: any) => {
        if (chunk.web) groundingSources.push({ title: chunk.web.title || "Reference", uri: chunk.web.uri, type: 'web' });
      });

      const analysis: ScamAnalysis = {
        isScam: !!data.is_scam,
        confidence: data.confidence_level === 'high' ? 0.95 : 0.6,
        scamType: data.scam_type || "Analysis",
        channel: 'text',
        threatLevel: data.is_scam ? (data.confidence_level === 'high' ? 'High' : 'Medium') : 'Low',
        summary: data.reasoning || "Scan complete.",
        safetyAlert: data.is_scam ? `Detection: Suspicious ${data.scam_type} pattern.` : "Clear.",
        extractedInfo: { upiIds: [], bankDetails: [], ifscCodes: [], phoneNumbers: [], links: [], cryptoWallets: [], fakeIdentities: [] },
        killChainStage: data.is_scam ? 'Exploitation' : 'Delivery',
        fingerprint: { primaryHandle: '', primaryPhone: '', primaryLink: '', category: data.scam_type || "Fraud" },
        recommendedActions: [data.recommended_action || "Stay vigilant."],
        groundingSources
      };

      if (analysis.isScam) {
        analysis.guardianGuidance = await generateGuardianGuidance(analysis);
      }
      return analysis;
    });
  } catch (error) {
    console.error("API failed, using local scan:", error);
    return performLocalScan(message);
  }
}

