export interface ApiStatus {
  isThrottled: boolean;
  lastThrottleTime: number;
  errorCount: number;
  currentIntensity: 'standard' | 'deep';
  defenseScope: 'National' | 'Global';
}

export const apiStatus: ApiStatus = {
  isThrottled: false,
  lastThrottleTime: 0,
  errorCount: 0,
  currentIntensity: 'standard',
  defenseScope: 'National'
};

const safeJsonParse = (text: string) => {
  if (!text) return {};
  try {
    const cleaned = text.replace(/```json\n?|```/g, '').trim();
    return JSON.parse(cleaned);
  } catch (e) {
    console.error("JSON Parse Error:", e);
    return {};
  }
};

async function withRetry<T>(fn: () => Promise<T>, fallback: T, retries = 1, delay = 1000): Promise<T> {
  try {
    const result = await fn();
    apiStatus.isThrottled = false;
    return result;
  } catch (error: any) {
    console.error("Gemini API Error:", error);

    // Check for 429 Resource Exhausted
    if (error?.message?.includes('429') || error?.status === 429 || error?.code === 429) {
      apiStatus.isThrottled = true;
      apiStatus.lastThrottleTime = Date.now();
      console.warn("API Quota Exhausted. Switching to Local Defense Node.");
      return fallback;
    }

    if (retries > 0) {
      await new Promise(resolve => setTimeout(resolve, delay));
      return withRetry(fn, fallback, retries - 1, delay * 2);
    }

    return fallback;
  }
}

