const performLocalScan = (message: string): ScamAnalysis => {
  const keywords = ['kyc', 'blocked', 'arrest', 'drug', 'fine', 'prize', 'winner', 'click here', 'login', 'police', 'upi', 'pay', 'electricity', 'bill'];
  const msgLower = message.toLowerCase();
  const found = keywords.filter(kw => msgLower.includes(kw));
  const isLikelyScam = found.length >= 2;

  return {
    isScam: isLikelyScam,
    confidence: 0.85,
    scamType: isLikelyScam ? "Pattern Recognition" : "Verified Safe",
    channel: 'text',
    threatLevel: isLikelyScam ? 'High' : 'Low',
    summary: isLikelyScam ? "Local heuristic scan detected high-pressure keywords used in Indian frauds." : "No immediate threat markers found in local scan.",
    safetyAlert: isLikelyScam ? "DANGER: High risk markers identified by Local Shield." : "Clear.",
    extractedInfo: { upiIds: [], bankDetails: [], ifscCodes: [], phoneNumbers: [], links: [], cryptoWallets: [], fakeIdentities: [] },
    killChainStage: isLikelyScam ? 'Delivery' : 'Reconnaissance',
    fingerprint: { primaryHandle: '', primaryPhone: '', primaryLink: '', category: 'Local_Heuristic' },
    recommendedActions: [isLikelyScam ? "Do not click links. Block sender immediately." : "Always stay vigilant."],
    guardianGuidance: {
        user_alert: isLikelyScam ? "Suspicious message detected by Local Defense Grid." : "No scam detected.",
        scam_type: isLikelyScam ? "Heuristic Match" : "Clean",
        risk_level: isLikelyScam ? 'high' : 'low',
        captured_evidence: "Logged to local device.",
        what_to_do_now: isLikelyScam ? ["Delete message.", "Report to 1930.", "Inform your bank."] : ["No action needed."]
    }
  };
};

export async function analyzeMessage(message: string): Promise<ScamAnalysis> {
  const localFallback = performLocalScan(message);

  return await withRetry(async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: message,
      config: {
        responseMimeType: "application/json",
        systemInstruction: HONEY_POT_SYSTEM_PROMPT,
        tools: [{ googleSearch: {} }]
      }
    });

    const data = safeJsonParse(response.text || "{}");
    const groundingSources: GroundingSource[] = [];
    response.candidates?.[0]?.groundingMetadata?.groundingChunks?.forEach((chunk: any) => {
      if (chunk.web) groundingSources.push({ title: chunk.web.title || "Reference", uri: chunk.web.uri, type: 'web' });
    });

    const analysis: ScamAnalysis = {
      isScam: !!data.is_scam,
      confidence: data.confidence_level === 'high' ? 0.95 : 0.6,
      scamType: data.scam_type || "Analysis",
      channel: 'text',
      threatLevel: data.is_scam ? (data.confidence_level === 'high' ? 'High' : 'Medium') : 'Low',
      summary: data.reasoning || "Scan complete.",
      safetyAlert: data.is_scam ? `Detection: Suspicious ${data.scam_type} pattern.` : "Clear.",
      extractedInfo: { upiIds: [], bankDetails: [], ifscCodes: [], phoneNumbers: [], links: [], cryptoWallets: [], fakeIdentities: [] },
      killChainStage: data.is_scam ? 'Exploitation' : 'Delivery',
      fingerprint: { primaryHandle: '', primaryPhone: '', primaryLink: '', category: data.scam_type || "Fraud" },
      recommendedActions: [data.recommended_action || "Stay vigilant."],
      groundingSources
    };

    if (analysis.isScam) {
      analysis.guardianGuidance = await generateGuardianGuidance(analysis);
    }
    return analysis;
  }, localFallback);
}

