export async function generateAgenticBait(sessionId: string, history: { role: string, content: string }[]): Promise<AgentResponse> {
  const fallback: AgentResponse = {
    conversation_id: sessionId,
    is_scam: true,
    scam_type: "Unknown",
    agent_reply: "I am having trouble understanding. Can you explain again? I need help with my bank account.",
    engagement: { active: true, turns: history.length },
    extracted_intelligence: { upi_ids: [], bank_accounts: [], ifsc_codes: [], phone_numbers: [], phishing_urls: [], payment_instructions: [] },
    confidence_score: 0.5
  };

  return await withRetry<AgentResponse>(async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: history.map(h => ({ role: h.role === 'scammer' ? 'user' : 'model', parts: [{ text: h.content }] })),
      config: {
        responseMimeType: "application/json",
        systemInstruction: "You are an Indian victim in a honeypot. Reply in Hinglish. Extract UPI IDs. Output JSON."
      }
    });
    const data = safeJsonParse(response.text || "{}");
    return {
      conversation_id: sessionId,
      is_scam: true,
      scam_type: (data.scam_type as any) || "Unknown",
      agent_reply: data.agent_reply || fallback.agent_reply,
      engagement: { active: true, turns: history.length },
      extracted_intelligence: data.extracted_intelligence || fallback.extracted_intelligence,
      confidence_score: 0.9
    };
  }, fallback);
}

