              <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce [animation-delay:0.4s]" />
            </div>
          </div>
        )}
      </div>

      <div className="p-8 bg-black/60 border-t border-white/5">
        <form 
          onSubmit={(e) => {
            e.preventDefault();
            handleManualScammerReply(input);
          }}
          className="relative"
        >
          <input 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            disabled={isTyping || isSimulatingScammer}
            placeholder="Type a manual response from the scammer..."
            className="w-full bg-slate-900 border border-white/10 rounded-2xl py-5 pl-8 pr-32 text-sm text-white focus:outline-none focus:ring-2 focus:ring-blue-600 disabled:opacity-50 transition-all font-medium placeholder:text-slate-600"
