  useEffect(() => {
    if (lastMessage && lastMessage.role === 'scammer' && !isTyping && !isSimulatingScammer) {
      // Small delay to feel human-like
      const timer = setTimeout(() => {
        runAgenticTurn(safeMessages);
      }, 1500);
      return () => clearTimeout(timer);
    }
  }, [lastMessage?.timestamp, lastMessage?.content]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [safeMessages.length, isTyping, isSimulatingScammer]);

  const runAgenticTurn = async (currentMessages: ChatMessage[]) => {
    if (isTyping) return;
    setIsTyping(true);
    console.debug(`[Honeypot] Initiating agentic turn for session ${sessionId}`);

